UPDATE equipment
SET equipment_name = #{equipmentName}, line_no = #{lineNo}, zone = #{zone}, manufacturer = #{manufacturer},
    cycle_time = #{cycleTime}, health_score = #{healthScore}, remaining_life = #{remainingLife}, replacement_date = #{replacementDate}
WHERE equipment_id = #{equipmentId}

UPDATE equipment
SET health_score = #{healthScore},
    accumulated_run_hours = #{accumulatedRunHours},
    remaining_life = #{remainingLife},
    replacement_date = #{replacementDate}
WHERE equipment_id = #{equipmentId}
